    adcs_status_t status;
    double d_norm;
    double abs_d;
    int sign;
    double out_mag;
    unint32 sat_mask = 0U;
    adcs_vec3_t cmd_out = {0.0, 0.0, 0.0};
    size_t i;
    const double *req_vals[] = {&requested_a_m2->x, &requested_a_m2->y, &requested_a_m2->z};
    double *cmd_vals[] = {&cmd_out.x, &cmd_out.y, &cmd_out.z};

    /* 1. Null check */
    if ((requested_a_m2 == NULL) || (duty == NULL)) {
        return ADCS_E_NULL;
    }

    /* 2. Finite check for input vector */
    if (!adcs_is_finite_vec3(requested_a_m2)) {
        return ADCS_E_RANGE;
    }

    /* 3. Parameter range checks */
    if ((!isfinite(full_scale_a_m2)) || (full_scale_a_m2 <= 0.0)) {
        return ADCS_E_RANGE;
    }
    if ((!isfinite(minimum_duty)) || (minimum_duty < 0.0) || (minimum_duty > 1.0)) {
        return ADCS_E_RANGE;
    }

    /* 4. Process each axis */
    for (i = 0; i < 3; ++i) {
        double val = *req_vals[i];

        /* Compute normalized magnitude and sign */
        d_norm = val / full_scale_a_m2;
        abs_d = fabs(d_norm);

        /* Determine sign to restore later */
        if (val >= 0.0) {
            sign = 1;
        } else {
            sign = -1;
        }

        /* Decision table based on abs_d */
        if (abs_d == 0.0) {
            out_mag = 0.0;
            /* Promotion bit clear: do nothing to sat_mask for this axis */
        } else if (abs_d < minimum_duty) {
            out_mag = minimum_duty;
            /* Promotion bit set */
            sat_mask |= (unint32)(1U << i);
        } else if (abs_d <= 1.0) {
            out_mag = abs_d;
            /* Promotion bit clear */
        } else {
            out_mag = 1.0;
            /* Promotion bit clear */
        }

        /* Restore sign */
        *cmd_vals[i] = out_mag * sign;
    }

    /* 5. Assign to output structure */
    duty->command = cmd_out;
    duty->saturated_axes = sat_mask;

    return ADCS_OK;
}

